    out = {}
    for name, target in sheets:
        root = ET.fromstring(z.read(target))
        rows = []
        for c in root.iter(f'{{{MAIN}}}c'):
            ref = c.get('r')
            t = c.get('t')
            v = c.find(f'{{{MAIN}}}v')
