import sys, zipfile
from xml.etree import ElementTree as ET

MAIN = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
REL = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'

def norm_target(t):
    t = t.lstrip('/')
    if not t.startswith('xl/'):
        t = 'xl/' + t
    return t

def parse_stdlib(path):
    z = zipfile.ZipFile(path)
    wb = ET.fromstring(z.read('xl/workbook.xml'))
    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {r.get('Id'): r.get('Target') for r in rels}
    sheets = []
    for sh in wb.find(f'{{{MAIN}}}sheets'):
        rid = sh.get(f'{{{REL}}}id')
        sheets.append((sh.get('name'), norm_target(rel_map[rid])))
    shared = []
    if 'xl/sharedStrings.xml' in z.namelist():
        ss = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in ss.findall(f'{{{MAIN}}}si'):
            shared.append(''.join(t.text or '' for t in si.iter(f'{{{MAIN}}}t')))
    out = {}
    for name, target in sheets:
        root = ET.fromstring(z.read(target))
        rows = []
        for c in root.iter(f'{{{MAIN}}}c'):
            ref = c.get('r')
            t = c.get('t')
            v = c.find(f'{{{MAIN}}}v')
            is_ = c.find(f'{{{MAIN}}}is')
            if t == 's' and v is not None:
                val = shared[int(v.text)]
            elif t == 'inlineStr' and is_ is not None:
                val = ''.join(x.text or '' for x in is_.iter(f'{{{MAIN}}}t'))
            elif v is not None:
                val = v.text
            else:
                val = None
            if val is not None:
                rows.append((ref, val))
        out[name] = rows
    return out

def to_number(v):
    try:
        return float(v)
    except (TypeError, ValueError):
        return None

path = "budget.xlsx"
sheets = parse_stdlib(path)
print("Parser: stdlib")
for name, rows in sheets.items():
    print(f"\n=== Sheet: {name} ===")
    for ref, val in rows:
        print(f"{ref}: {val!r}")

print("\n--- Numeric sums ---")
grand = 0.0
for name, rows in sheets.items():
    total = sum(n for _, v in rows if (n := to_number(v)) is not None)
    print(f"{name}: {total}")
    grand += total
print(f"WORKBOOK TOTAL: {grand}")
